(function(){
  'use strict';
  const form=document.getElementById('login-form'),tabs=[document.getElementById('signin-tab'),document.getElementById('signup-tab')];
  let signup=false;
  function mode(create){signup=create;tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===Number(create)));tab.tabIndex=i===Number(create)?0:-1;});document.getElementById('account-panel').setAttribute('aria-labelledby',tabs[Number(create)].id);document.getElementById('account-names').hidden=!create;document.getElementById('account-names').disabled=!create;document.getElementById('account-tier').hidden=!create;form.elements.tier.disabled=!create;form.elements.password.autocomplete=create?'new-password':'current-password';document.getElementById('account-title').textContent=create?'Your next chapter starts here.':'Welcome back.';document.getElementById('account-intro').textContent=create?'Choose your membership and begin with intention.':'Continue your leadership journey.';form.querySelector('.submit').textContent=create?'Create Account →':'Sign In →';document.getElementById('account-error').textContent='';}
  tabs.forEach((tab,i)=>{tab.onclick=()=>mode(Boolean(i));tab.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?1:1-i;mode(Boolean(index));tabs[index].focus();}};});
  function destination(){const next=new URLSearchParams(location.search).get('next');if(!next)return '/app';try{const url=new URL(next,location.origin);if(url.origin===location.origin&&next.startsWith('/')&&!next.startsWith('//')&&!/^\/(?:login|auth)(?:\/|$)/.test(url.pathname))return url.pathname+url.search+url.hash;}catch{}return '/app';}
  form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('.submit');button.disabled=true;document.getElementById('account-error').textContent='';try{const response=await fetch('/api/auth/'+(signup?'signup':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const data=await response.json();if(!response.ok)throw Error(data.error||'Unable to continue. Please try again.');location.replace(destination());}catch(error){document.getElementById('account-error').textContent=error.message;button.disabled=false;}};
})();